select id, merchant_id, service_date, meal_slot_id, family_id, ingredient_name, quantity, unit, remark, checked
from temp_purchase_items
where merchant_id = #{merchantId}
  and service_date = #{date}

  and (family_id = #{familyId} or family_id is null)

order by checked asc, id asc

